    #[test]
    fn test_all_lowercase() {
        let input: Vec<char> = "abcdefz".chars().collect();
        let output: Vec<char> = flip_case(input);
        assert_eq!(output.iter().collect::<String>(), "ABCDEFZ");
    }

    #[test]
    fn test_all_uppercase() {
        let input: Vec<char> = "XYZ".chars().collect();
        let output: Vec<char> = flip_case(input);
        assert_eq!(output.iter().collect::<String>(), "xyz");
    }

